func Check(config Config) Report {
	profile := deterministicio.Default()
	profileIdentity := profile.Identity()
	report := Report{
		Schema: reportSchema, Host: config.HostOS + "/" + config.HostArch,
		SupportedPlatforms:      append([]string(nil), gomadversion.SupportedPlatforms[:]...),
		BoundaryManifestVersion: gomadversion.BoundaryManifestVersion,
		IOInventorySHA256:       record.SHA256(profileIdentity.InventorySHA256), IOImplementationSHA256: record.SHA256(profileIdentity.ImplementationSHA256),
		Adapters:           []Adapter{},
		InstallationSource: config.InstallationSource,
		ToolchainRoot:      config.ToolchainRoot,
		ArtifactDirectory:  config.ArtifactRoot,
		RepairInstruction:  config.RepairInstruction,
		Checks:             make([]CheckResult, 0, 4+len(profile.Adapters())),
	}
	for _, identity := range profile.Adapters() {
		report.Adapters = append(report.Adapters, Adapter{
			Module: identity.Module, Version: identity.Version, Sum: identity.Sum, Status: "available",
		})
	}
	report.Checks = append(report.Checks, hostCheck(report.Host, report.SupportedPlatforms))
	identity, err := target.ReadToolchainIdentity(config.ToolchainRoot)
	if err != nil {
		report.Checks = append(report.Checks, failedCheck("toolchain", err.Error()+"; "+report.RepairInstruction))
	} else {
		report.GoVersion = identity.GoVersion
		report.ToolchainBuild = identity.BuildKey
		report.Checks = append(report.Checks, passedCheck("toolchain", identity.GoVersion+" build="+identity.BuildKey))
	}
	runnerDigest, err := digestRunner(config.RunnerPath)
	if err != nil {
		report.Checks = append(report.Checks, failedCheck("runner", err.Error()+"; reinstall the Gomad executable at "+config.RunnerPath))
	} else {
		report.RunnerBuild = runnerDigest
		report.Checks = append(report.Checks, passedCheck("runner", string(runnerDigest)))
	}
	for _, adapter := range report.Adapters {
		report.Checks = append(report.Checks, passedCheck("adapter:"+adapter.Module, adapter.Module+"@"+adapter.Version+" "+adapter.Sum))
	}
	if err := checkArtifactDirectory(config.ArtifactRoot); err != nil {
		report.Checks = append(report.Checks, failedCheck("artifacts", err.Error()))
	} else {
		report.Checks = append(report.Checks, passedCheck("artifacts", config.ArtifactRoot))
	}
	report.Available = true
	for _, check := range report.Checks {
		if check.Status != "ok" {
			report.Available = false
			break
		}
	}
	return report
}

func hostCheck(host string, supported []string) CheckResult {
	for _, platform := range supported {
		if host == platform {
			return passedCheck("host", host)
		}
	}
	return failedCheck("host", host+" is unsupported; supported="+strings.Join(supported, ","))
}

func (app application) runDoctor(arguments []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("gomad doctor", flag.ContinueOnError)
	flags.SetOutput(stderr)
	artifacts := flags.String("artifacts", ".gomad/artifacts", "artifact root to verify")
	toolchainRoot := flags.String("toolchain-root", "", "absolute pinned toolchain root")
	jsonOutput := flags.Bool("json", false, "emit stable JSON")
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if flags.NArg() != 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	executable, err := app.executablePath()
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	executable, err = absoluteExecutable(executable)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 3
	}
	artifactRoot, err := filepath.Abs(*artifacts)
	if err != nil {
		fmt.Fprintf(stderr, "resolve artifact directory: %v\n", err)
		return 2
	}
	resolved, err := app.resolveInstallation(executable, *toolchainRoot)
	if err != nil {
		if _, writeErr := fmt.Fprintf(stderr, "resolve Gomad installation: %v\n", err); writeErr != nil {
			return 3
		}
		return 2
	}
	report := Check(Config{
		ToolchainRoot: resolved.ToolchainRoot, InstallationSource: resolved.Source, RepairInstruction: resolved.RepairInstruction,
		RunnerPath: executable, ArtifactRoot: artifactRoot, HostOS: runtime.GOOS, HostArch: runtime.GOARCH,
	})
	if *jsonOutput {
		encoded, marshalErr := json.Marshal(report)
		if marshalErr != nil {
			fmt.Fprintf(stderr, "encode doctor report: %v\n", marshalErr)
			return 3
		}
		fmt.Fprintf(stdout, "%s\n", encoded)
	} else {
		fmt.Fprintf(stdout, "gomad doctor: available=%t host=%s go=%s toolchain=%s runner=%s boundary=%s\n", report.Available, report.Host, report.GoVersion, report.ToolchainBuild, report.RunnerBuild, report.BoundaryManifestVersion)
		for _, check := range report.Checks {
			fmt.Fprintf(stdout, "%-10s %-5s %s\n", check.Name, check.Status, check.Detail)
		}
		if _, err := fmt.Fprintf(stdout, "installation: source=%s toolchain=%s\nrepair: %s\n", report.InstallationSource, report.ToolchainRoot, report.RepairInstruction); err != nil {
			return 3
		}
	}
	if !report.Available {
		return 1
	}
	return 0
}

